from pydantic import BaseModel

class LandlordInstructionList(BaseModel):
    __root__: list[LandlordInstruction]

instructions_obj = query_ai_assistant(
    "Read the following text and extract all payment instructions from the landlord. For each instruction, provide the action (such as 'pay' or 'transfer'), the recipient (name or IBAN if available), the amount, the subject or reason for payment, and the date the payment should be made. If there are multiple instructions, return a list of them.",
    LandlordInstructionList
)

instructions = instructions_obj.__root__

for instr in instructions:
    if instr.action.lower() in ['pay', 'transfer', 'send']:
        send_money(instr.recipient, instr.amount, instr.subject, instr.date)
```

